var _ = Describe("TerminalError", func() {
	It("wraps and detects permanent errors", func() {
		base := errors.New("invalid version")
		err := AsTerminal(base)

		Expect(IsTerminal(err)).To(BeTrue())
		Expect(IsTerminal(base)).To(BeFalse())
