				opensearchv1.ComponentStatus{Component: "Upgrader", Description: "data", Status: "Upgraded"},
			))
			Expect(helpers.IsUpgradeInProgress(cluster.Status)).To(BeTrue())
		})
	})

	Describe("custom image pinned", func() {
