						Component: "tiered",
						Roles:     []string{role},
					}
					Expect(helpers.HasDataRole(&nodePool)).To(BeTrue(), "role %s should count as a data role", role)
				}
			})
		})

		Context("with non-data roles that merely look similar", func() {
