			BeforeEach(func() {
				instance.Status.ExistingComponentTemplate = ptr.To(true)
			})
			It("should do nothing and exit", func() {
				Expect(reconciler.Delete()).To(Succeed())
			})
		})

		Context("existing status is false", func() {
			BeforeEach(func() {
				instance.Status.ExistingComponentTemplate = ptr.To(false)
			})

			When("cluster does not exist", func() {
				BeforeEach(func() {
					instance.Spec.OpensearchRef.Name = "doesnotexist"
					mockClient.EXPECT().GetOpenSearchCluster(mock.Anything, mock.Anything).Return(opensearchv1.OpenSearchCluster{}, NotFoundError())
				})
				It("should do nothing and exit", func() {
					Expect(reconciler.Delete()).To(Succeed())
				})
			})

			When("componenttemplate does not exist", func() {
				BeforeEach(func() {
					mockClient.EXPECT().GetOpenSearchCluster(mock.Anything, mock.Anything).Return(*cluster, nil)
					transport.RegisterResponder(
						http.MethodGet,
						clusterUrl,
						httpmock.NewStringResponder(200, "OK").Times(2, failMessage),
					)
					transport.RegisterResponder(
						http.MethodHead,
						clusterUrl,
						httpmock.NewStringResponder(200, "OK").Once(failMessage),
					)
					transport.RegisterResponder(
						http.MethodHead,
						fmt.Sprintf("%s_component_template/my-template", clusterUrl),
						httpmock.NewStringResponder(404, "does not exist").Once(failMessage),
					)
				})

				It("should do nothing and exit", func() {
					Expect(reconciler.Delete()).To(Succeed())
					Expect(transport.GetTotalCallCount()).To(Equal(transport.NumResponders() + 1))
				})
			})

			When("componenttemplate does exist", func() {
				BeforeEach(func() {
					mockClient.EXPECT().GetOpenSearchCluster(mock.Anything, mock.Anything).Return(*cluster, nil)
					componentTemplateUrl := fmt.Sprintf("%s_component_template/my-template", clusterUrl)

					transport.RegisterResponder(
						http.MethodGet,
						clusterUrl,
						httpmock.NewStringResponder(200, "OK").Times(2, failMessage),
					)
					transport.RegisterResponder(
						http.MethodHead,
						clusterUrl,
						httpmock.NewStringResponder(200, "OK").Once(failMessage),
					)
					transport.RegisterResponder(
						http.MethodHead,
						componentTemplateUrl,
						httpmock.NewStringResponder(200, "OK").Once(failMessage),
					)
					transport.RegisterResponder(
						http.MethodDelete,
						componentTemplateUrl,
						httpmock.NewStringResponder(200, "OK").Once(failMessage),
					)
				})

				It("should delete the componenttemplate", func() {
					Expect(reconciler.Delete()).To(Succeed())
					Expect(transport.GetTotalCallCount()).To(Equal(transport.NumResponders() + 1))
				})
			})
		})
	})
})

package reconcilers

import (
	"context"
	"fmt"
	"net/http"

	"k8s.io/utils/ptr"

	"github.com/jarcoal/httpmock"
	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
	opensearchv1 "github.com/opensearch-project/opensearch-k8s-operator/opensearch-operator/api/opensearch.org/v1"
	"github.com/opensearch-project/opensearch-k8s-operator/opensearch-operator/mocks/github.com/opensearch-project/opensearch-k8s-operator/opensearch-operator/pkg/reconcilers/k8s"
	"github.com/opensearch-project/opensearch-k8s-operator/opensearch-operator/opensearch-gateway/requests"
	"github.com/opensearch-project/opensearch-k8s-operator/opensearch-operator/opensearch-gateway/responses"
	"github.com/opensearch-project/opensearch-k8s-operator/opensearch-operator/pkg/helpers"
	"github.com/stretchr/testify/mock"
	corev1 "k8s.io/api/core/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/types"
	"k8s.io/client-go/tools/record"
	"sigs.k8s.io/controller-runtime/pkg/client"
	"sigs.k8s.io/controller-runtime/pkg/log"
)

var _ = Describe("tenant reconciler", func() {
	var (
		transport  *httpmock.MockTransport
		reconciler *TenantReconciler
		instance   *opensearchv1.OpensearchTenant
		recorder   *record.FakeRecorder
		mockClient *k8s.MockK8sClient

		// Objects
		cluster    *opensearchv1.OpenSearchCluster
		clusterUrl string
	)

	BeforeEach(func() {
		mockClient = k8s.NewMockK8sClient(GinkgoT())
		transport = httpmock.NewMockTransport()
		transport.RegisterNoResponder(httpmock.NewNotFoundResponder(failMessage))
		instance = &opensearchv1.OpensearchTenant{
			ObjectMeta: metav1.ObjectMeta{
				Name:      "test-tenant",
				Namespace: "test-tenant",
				UID:       "testuid",
			},
			Spec: opensearchv1.OpensearchTenantSpec{
				OpensearchRef: corev1.LocalObjectReference{
					Name: "test-cluster",
				},
				Description: "test-description",
			},
		}

		cluster = &opensearchv1.OpenSearchCluster{
			ObjectMeta: metav1.ObjectMeta{
				Name:      "test-cluster",
				Namespace: "test-tenant",
			},
			Spec: opensearchv1.ClusterSpec{
				General: opensearchv1.GeneralConfig{
					ServiceName: "test-cluster",
					HttpPort:    9200,
				},
				NodePools: []opensearchv1.NodePool{
					{
						Component: "node",
						Roles: []string{
							"master",
							"data",
						},
					},
				},
			},
		}
		clusterUrl = fmt.Sprintf("%s/", helpers.ClusterURL(cluster))
		// Mock admin credentials secret for all tests (available when CreateClientForCluster is invoked)
		adminSecret := corev1.Secret{
			ObjectMeta: metav1.ObjectMeta{
				Name:      "test-cluster-admin-password",
				Namespace: "test-tenant",
			},
			Data: map[string][]byte{
				"username": []byte("admin"),
				"password": []byte("admin"),
			},
		}
		mockClient.On("GetSecret", "test-cluster-admin-password", "test-tenant").Return(func(string, string) corev1.Secret {
			return adminSecret
		}, nil).Maybe()
	})

	JustBeforeEach(func() {
		options := ReconcilerOptions{}
		options.apply(WithOSClientTransport(transport), WithUpdateStatus(false))
		reconciler = &TenantReconciler{
			client:            mockClient,
			ctx:               context.Background(),
			ReconcilerOptions: options,
			recorder:          recorder,
			instance:          instance,
			logger:            log.FromContext(context.Background()),
		}
	})

	When("cluster doesn't exist", func() {
		BeforeEach(func() {
			instance.Spec.OpensearchRef.Name = "doesnotexist"
			mockClient.EXPECT().GetOpenSearchCluster(mock.Anything, mock.Anything).Return(opensearchv1.OpenSearchCluster{}, NotFoundError())
			recorder = record.NewFakeRecorder(1)
		})
		It("should wait for the cluster to exist", func() {
			go func() {
				defer GinkgoRecover()
				defer close(recorder.Events)
				result, err := reconciler.Reconcile()
				Expect(err).NotTo(HaveOccurred())
				Expect(result.Requeue).To(BeTrue())
			}()
			var events []string
			for msg := range recorder.Events {
				events = append(events, msg)
			}
			Expect(len(events)).To(Equal(1))
			Expect(events[0]).To(Equal(fmt.Sprintf("Normal %s waiting for opensearch cluster to exist", opensearchPending)))
		})
	})

	When("cluster doesn't match status", func() {
		BeforeEach(func() {
			uid := types.UID("someuid")
			instance.Status.ManagedCluster = &uid
			mockClient.EXPECT().GetOpenSearchCluster(mock.Anything, mock.Anything).Return(*cluster, nil)
			recorder = record.NewFakeRecorder(1)
		})
		It("should error", func() {
			go func() {
				defer GinkgoRecover()
				defer close(recorder.Events)
				_, err := reconciler.Reconcile()
				Expect(err).To(HaveOccurred())
			}()
			var events []string
			for msg := range recorder.Events {
				events = append(events, msg)
			}
			Expect(len(events)).To(Equal(1))
			Expect(events[0]).To(Equal(fmt.Sprintf("Warning %s cannot change the cluster an tenant refers to", opensearchRefMismatch)))
		})
	})

	When("cluster is not ready", func() {
		BeforeEach(func() {
			recorder = record.NewFakeRecorder(1)
			mockClient.EXPECT().GetOpenSearchCluster(mock.Anything, mock.Anything).Return(*cluster, nil)
		})
		It("should wait for the cluster to be running", func() {
			go func() {
				defer GinkgoRecover()
				defer close(recorder.Events)
				result, err := reconciler.Reconcile()
				Expect(err).NotTo(HaveOccurred())
				Expect(result.Requeue).To(BeTrue())
			}()
			var events []string
			for msg := range recorder.Events {
				events = append(events, msg)
			}
			Expect(len(events)).To(Equal(1))
			Expect(events[0]).To(Equal(fmt.Sprintf("Normal %s waiting for opensearch cluster status to be running", opensearchPending)))
		})
	})

	Context("cluster is ready", func() {
		extraContextCalls := 1
		BeforeEach(func() {
			cluster.Status.Phase = opensearchv1.PhaseRunning
			cluster.Status.ComponentsStatus = []opensearchv1.ComponentStatus{}
			mockClient.EXPECT().GetOpenSearchCluster(mock.Anything, mock.Anything).Return(*cluster, nil)
			transport.RegisterResponder(
				http.MethodGet,
				clusterUrl,
				httpmock.NewStringResponder(200, "OK").Times(2, failMessage),
			)

			transport.RegisterResponder(
				http.MethodHead,
				clusterUrl,
				httpmock.NewStringResponder(200, "OK").Once(failMessage),
			)
		})

		When("existing status is true", func() {
			BeforeEach(func() {
				instance.Status.ExistingTenant = ptr.To(true)
				mockClient.EXPECT().GetOpenSearchCluster(mock.Anything, mock.Anything).Return(*cluster, nil)
			})

			It("should do nothing", func() {
				_, err := reconciler.Reconcile()
				Expect(err).ToNot(HaveOccurred())
			})
		})

		When("existing status is nil", func() {
			localExtraCalls := 4
			BeforeEach(func() {
				tenantRequest := requests.Tenant{
					Description: "test-description",
				}
				recorder = record.NewFakeRecorder(1)
				transport.RegisterResponder(
					http.MethodGet,
					clusterUrl,
					httpmock.NewStringResponder(200, "OK").Times(4, failMessage),
				)
				transport.RegisterResponder(
					http.MethodHead,
					clusterUrl,
					httpmock.NewStringResponder(200, "OK").Times(2, failMessage),
				)
				transport.RegisterResponder(
					http.MethodGet,
					fmt.Sprintf(
						"%s_plugins/_security/api/tenants/%s",
						clusterUrl,
						instance.Name,
					),
					httpmock.NewJsonResponderOrPanic(200, responses.GetTenantResponse{
						instance.Name: tenantRequest,
					}).Then(
						httpmock.NewStringResponder(404, "does not exist"),
					).Then(
						httpmock.NewNotFoundResponder(failMessage),
					),
				)
			})

			It("should do nothing and emit a unit test event", func() {
				go func() {
					defer GinkgoRecover()
					defer close(recorder.Events)
					_, err := reconciler.Reconcile()
					Expect(err).ToNot(HaveOccurred())
					_, err = reconciler.Reconcile()
					Expect(err).ToNot(HaveOccurred())
					// Confirm all responders have been called
					Expect(transport.GetTotalCallCount()).To(Equal(transport.NumResponders() + extraContextCalls + localExtraCalls))
				}()
				var events []string
				for msg := range recorder.Events {
					events = append(events, msg)
				}
				Expect(len(events)).To(Equal(2))
				Expect(events[0]).To(Equal("Normal UnitTest exists is true"))
				Expect(events[1]).To(Equal("Normal UnitTest exists is false"))
			})
		})

		When("existing status is nil but a concurrent status write already set it", func() {
			// Regression test for the migration race: the migration controller
			// creates the twin with an empty status and restores the real status
			// afterwards via UdateObjectStatus. If this reconciler's own "does it
			// already exist in Opensearch" probe races that restore, it must not
			// clobber the concurrently-written value.
			JustBeforeEach(func() {
				reconciler.updateStatus = ptr.To(true)
			})

			BeforeEach(func() {
				instance.Status.ManagedCluster = &cluster.UID
				tenantRequest := requests.Tenant{
					Description: "test-description",
				}
				transport.RegisterResponder(
					http.MethodGet,
					fmt.Sprintf(
						"%s_plugins/_security/api/tenants/%s",
						clusterUrl,
						instance.Name,
					),
					httpmock.NewJsonResponderOrPanic(200, responses.GetTenantResponse{
						instance.Name: tenantRequest,
					}),
				)
				// The first UdateObjectStatus call is the reconciler's "does it
				// already exist in Opensearch" probe; simulate the migration
				// controller's status restore landing right before it runs.
				mockClient.EXPECT().UdateObjectStatus(mock.Anything, mock.Anything).RunAndReturn(
					func(obj client.Object, f func(client.Object)) error {
						obj.(*opensearchv1.OpensearchTenant).Status.ExistingTenant = ptr.To(false)
						f(obj)
						return nil
					},
				).Once()
				// Later UdateObjectStatus calls (e.g. the deferred reason/state
				// write) behave normally.
				mockClient.EXPECT().UdateObjectStatus(mock.Anything, mock.Anything).RunAndReturn(
					func(obj client.Object, f func(client.Object)) error {
						f(obj)
						return nil
					},
				)
			})

			It("keeps the concurrently-written value instead of marking it existing", func() {
				_, err := reconciler.Reconcile()
				Expect(err).ToNot(HaveOccurred())
				Expect(instance.Status.ExistingTenant).ToNot(BeNil())
				Expect(*instance.Status.ExistingTenant).To(BeFalse())
				Expect(instance.Status.State).ToNot(Equal(opensearchv1.OpensearchTenantIgnored))
			})
		})

		When("probe marks existing but a concurrent write marks it managed before deferred status", func() {
			// Residual race: this reconcile already decided the object was
			// pre-existing (reason=exists) before the migration restore landed.
			// The deferred status write must not stamp IGNORED over the
			// concurrently-restored ExistingTenant=false.
			JustBeforeEach(func() {
				reconciler.updateStatus = ptr.To(true)
			})

			BeforeEach(func() {
				instance.Status.ManagedCluster = &cluster.UID
				transport.RegisterResponder(
					http.MethodGet,
					fmt.Sprintf(
						"%s_plugins/_security/api/tenants/%s",
						clusterUrl,
						instance.Name,
					),
					httpmock.NewJsonResponderOrPanic(200, responses.GetTenantResponse{
						instance.Name: requests.Tenant{Description: "test-description"},
					}),
				)
				mockClient.EXPECT().UdateObjectStatus(mock.Anything, mock.Anything).RunAndReturn(
					func(obj client.Object, f func(client.Object)) error {
						f(obj)
						return nil
					},
				).Once()
				mockClient.EXPECT().UdateObjectStatus(mock.Anything, mock.Anything).RunAndReturn(
					func(obj client.Object, f func(client.Object)) error {
						obj.(*opensearchv1.OpensearchTenant).Status.ExistingTenant = ptr.To(false)
						f(obj)
						return nil
					},
				)
			})

			It("does not stamp IGNORED over the concurrently-written managed status", func() {
				_, err := reconciler.Reconcile()
				Expect(err).ToNot(HaveOccurred())
				Expect(instance.Status.ExistingTenant).ToNot(BeNil())
				Expect(*instance.Status.ExistingTenant).To(BeFalse())
				Expect(instance.Status.State).ToNot(Equal(opensearchv1.OpensearchTenantIgnored))
			})
		})

		When("existing status is true", func() {
			BeforeEach(func() {
				instance.Status.ExistingTenant = ptr.To(true)
				mockClient.EXPECT().GetOpenSearchCluster(mock.Anything, mock.Anything).Return(*cluster, nil)
			})
			It("should do nothing", func() {
				_, err := reconciler.Reconcile()
				Expect(err).ToNot(HaveOccurred())
			})
		})

		When("existing status is false", func() {
			BeforeEach(func() {
				instance.Status.ExistingTenant = ptr.To(false)
				mockClient.EXPECT().GetOpenSearchCluster(mock.Anything, mock.Anything).Return(*cluster, nil)
			})

			When("tenant exists in opensearch and is the same", func() {
				BeforeEach(func() {
					tenantRequest := requests.Tenant{
						Description: "test-description",
					}
					transport.RegisterResponder(
						http.MethodGet,
						fmt.Sprintf(
							"%s_plugins/_security/api/tenants/%s",
							clusterUrl,
							instance.Name,
						),
						httpmock.NewJsonResponderOrPanic(200, responses.GetTenantResponse{
							instance.Name: tenantRequest,
						}).Once(failMessage),
					)
				})
				It("should do nothing", func() {
					_, err := reconciler.Reconcile()
					Expect(err).ToNot(HaveOccurred())
					Expect(transport.GetTotalCallCount()).To(Equal(transport.NumResponders() + extraContextCalls))
				})
			})
			When("tenant exists in opensearch and is not the same", func() {
				BeforeEach(func() {
					recorder = record.NewFakeRecorder(1)
					tenantRequest := requests.Tenant{
						Description: "some-other-description",
					}
					transport.RegisterResponder(
						http.MethodGet,
						fmt.Sprintf(
							"%s_plugins/_security/api/tenants/%s",
							clusterUrl,
							instance.Name,
						),
						httpmock.NewJsonResponderOrPanic(200, responses.GetTenantResponse{
							instance.Name: tenantRequest,
						}).Once(failMessage),
					)
					transport.RegisterResponder(
						http.MethodPut,
						fmt.Sprintf(
							"%s_plugins/_security/api/tenants/%s",
							clusterUrl,
							instance.Name,
						),
						httpmock.NewStringResponder(200, "OK").Once(failMessage),
					)
				})
				It("should update the tenant", func() {
					go func() {
						defer GinkgoRecover()
						defer close(recorder.Events)
						_, err := reconciler.Reconcile()
						Expect(err).ToNot(HaveOccurred())
						// Confirm all responders have been called
						Expect(transport.GetTotalCallCount()).To(Equal(transport.NumResponders() + extraContextCalls))
					}()
					var events []string
					for msg := range recorder.Events {
						events = append(events, msg)
					}
					Expect(len(events)).To(Equal(1))
					Expect(events[0]).To(Equal(fmt.Sprintf("Normal %s tenant updated in opensearch", opensearchAPIUpdated)))
				})
			})
			When("tenant doesn't exist in opensearch", func() {
				BeforeEach(func() {
					recorder = record.NewFakeRecorder(1)
					transport.RegisterResponder(
						http.MethodGet,
						fmt.Sprintf(
							"%s_plugins/_security/api/tenants/%s",
							clusterUrl,
							instance.Name,
						),
						httpmock.NewStringResponder(404, "does not exist").Once(failMessage),
					)
					transport.RegisterResponder(
						http.MethodPut,
						fmt.Sprintf(
							"%s_plugins/_security/api/tenants/%s",
							clusterUrl,
							instance.Name,
						),
						httpmock.NewStringResponder(200, "OK").Once(failMessage),
					)
				})
				It("should create the tenant", func() {
					go func() {
						defer GinkgoRecover()
						defer close(recorder.Events)
						_, err := reconciler.Reconcile()
						Expect(err).ToNot(HaveOccurred())
						// Confirm all responders have been called
						Expect(transport.GetTotalCallCount()).To(Equal(transport.NumResponders() + extraContextCalls))
					}()
					var events []string
					for msg := range recorder.Events {
						events = append(events, msg)
					}
					Expect(len(events)).To(Equal(1))
					Expect(events[0]).To(Equal(fmt.Sprintf("Normal %s tenant updated in opensearch", opensearchAPIUpdated)))
				})
			})
		})
	})

	Context("deletions", func() {
		When("existing status is nil", func() {
			It("should do nothing and exit", func() {
				Expect(reconciler.Delete()).To(Succeed())
			})
		})

		When("existing status is true", func() {
			BeforeEach(func() {
				instance.Status.ExistingTenant = ptr.To(true)
			})
			It("should do nothing and exit", func() {
				Expect(reconciler.Delete()).To(Succeed())
			})
		})

		Context("existing status is false", func() {
			BeforeEach(func() {
				instance.Status.ExistingTenant = ptr.To(false)
			})

			When("cluster does not exist", func() {
				BeforeEach(func() {
					instance.Spec.OpensearchRef.Name = "doesnotexist"
					mockClient.EXPECT().GetOpenSearchCluster(mock.Anything, mock.Anything).Return(opensearchv1.OpenSearchCluster{}, NotFoundError())
				})
				It("should do nothing and exit", func() {
					Expect(reconciler.Delete()).To(Succeed())
				})
			})

			When("tenant does not exist", func() {
				BeforeEach(func() {
					mockClient.EXPECT().GetOpenSearchCluster(mock.Anything, mock.Anything).Return(*cluster, nil)
					transport.RegisterResponder(
						http.MethodGet,
						clusterUrl,
						httpmock.NewStringResponder(200, "OK").Times(2, failMessage),
					)
					transport.RegisterResponder(
						http.MethodHead,
						clusterUrl,
						httpmock.NewStringResponder(200, "OK").Once(failMessage),
					)
					transport.RegisterResponder(
						http.MethodGet,
						fmt.Sprintf(
							"%s_plugins/_security/api/tenants/%s",
							clusterUrl,
							instance.Name,
						),
						httpmock.NewStringResponder(404, "does not exist").Once(failMessage),
					)
				})
				It("should do nothing and exit", func() {
					Expect(reconciler.Delete()).To(Succeed())
					Expect(transport.GetTotalCallCount()).To(Equal(transport.NumResponders() + 1))
				})
			})
			When("tenant does exist", func() {
				BeforeEach(func() {
					mockClient.EXPECT().GetOpenSearchCluster(mock.Anything, mock.Anything).Return(*cluster, nil)
					transport.RegisterResponder(
						http.MethodGet,
						clusterUrl,
						httpmock.NewStringResponder(200, "OK").Times(2, failMessage),
					)
					transport.RegisterResponder(
						http.MethodHead,
						clusterUrl,
						httpmock.NewStringResponder(200, "OK").Once(failMessage),
					)
					transport.RegisterResponder(
						http.MethodGet,
						fmt.Sprintf(
							"%s_plugins/_security/api/tenants/%s",
							clusterUrl,
							instance.Name,
						),
						httpmock.NewStringResponder(200, "OK").Once(failMessage),
					)
					transport.RegisterResponder(
						http.MethodDelete,
						fmt.Sprintf(
							"%s_plugins/_security/api/tenants/%s",
							clusterUrl,
							instance.Name,
						),
						httpmock.NewStringResponder(200, "OK").Once(failMessage),
					)
				})
				It("should delete the tenant", func() {
					Expect(reconciler.Delete()).To(Succeed())
					Expect(transport.GetTotalCallCount()).To(Equal(transport.NumResponders() + 1))
				})
			})
		})
	})
})
